import React, { HTMLAttributes } from 'react';

import { dateRangeToLocaleString, getDiffDate } from '@helpers/dateHelper';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import PohCol from '@ui-kit/layout/Col';
import PohRow from '@ui-kit/layout/Row';

import { IWorkoutFull } from '../@types/workouts.types';

interface IWorkoutStatProps {
  data: IWorkoutFull;
}

interface IStatItemProps extends HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
}

const StatItem: React.FC<IStatItemProps> = ({ children, label }) => {
  return (
    <PohCol xs={4} sm={4} md={3} lg={2}>
      <h4 className="m-0">
        <strong className="text-success">{children}</strong>
      </h4>
      <small className="d-block text-muted mt-n1">{label}</small>
    </PohCol>
  );
};

const WorkoutStat: React.FC<IWorkoutStatProps> = ({ data }) => {
  return (
    <PohRow>
      <StatItem label="Расстояние">{formatDistance(data.distance)}</StatItem>
      <StatItem label="Время" title={dateRangeToLocaleString(data.date_start, data.date_finish)}>
        {getDiffDate(data.date_start, data.date_finish).toLocaleTimeString()}
      </StatItem>
      <StatItem label="Средняя скорость">{round(data.speed_avg / 10, 1)}&thinsp;км/ч</StatItem>
      <StatItem label="Средний темп">
        {getDiffDate(
          new Date(),
          new Date(new Date().getTime() + round(60 / (data.speed_avg / 10), 2) * 60000),
        )
          .toLocaleTimeString()
          .substring(3)}
        /км
      </StatItem>
      <StatItem label="Общий подъем">{formatAltitude(data.alt_ascent)}</StatItem>
      <StatItem label="Средняя ЧП">{data.hr_avg ?? '-'}</StatItem>
    </PohRow>
  );
};

export default WorkoutStat;
